const nm=s=>s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
const tx=s=>" "+nm(s).replace(/[^a-z0-9\s]/g," ").replace(/\s+/g," ").trim()+" ";

function analyze(){const m=[],{ph,tb,lv}=S;
if(ph<6.5)m.push(`pH bajo (${ph.toFixed(1)}): revisa el carbón y recalibra la sonda.`);else if(ph>8.5)m.push(`pH alto (${ph.toFixed(1)}): revisa la mineralización.`);
if(tb>5)m.push(`Turbidez alta (${tb.toFixed(1)} NTU): cambia el filtro de sedimentos ya.`);else if(tb>=1)m.push(`Turbidez moderada (${tb.toFixed(1)} NTU): vigila el filtro de sedimentos.`);
if(lv<20)m.push(`Nivel bajo (${Math.round(lv)}%): enciende la bomba.`);else if(lv>80)m.push(`Tanque casi lleno (${Math.round(lv)}%): detén la bomba.`);
return m.length?m.join(" "):`Todo en orden pH ${ph.toFixed(1)}, turbidez ${tb.toFixed(1)} NTU, nivel ${Math.round(lv)}%.`}

