const U={"celsius>fahrenheit":v=>v*9/5+32,"fahrenheit>celsius":v=>(v-32)*5/9,"km>millas":v=>v*.621371,"millas>km":v=>v*1.609344,"kg>libras":v=>v*2.20462,"libras>kg":v=>v/2.20462,"litros>galones":v=>v*.264172,"galones>litros":v=>v/.264172,"metros>pies":v=>v*3.28084,"pies>metros":v=>v/3.28084};
const lev=(a,b)=>{if(Math.abs(a.length-b.length)>1)return 9;let p=[...Array(b.length+1).keys()];for(let i=1;i<=a.length;i++){const c=[i];for(let j=1;j<=b.length;j++)c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]==b[j-1]?0:1));p=c}return p[b.length]};
const fmt=n=>+n.toFixed(6);

function special(raw){
let low=nm(raw).replace(/kilometros?/g,"km").replace(/kilogramos?|kilos?/g,"kg").replace(/grados /g,""),m;
if(m=low.match(/raiz(?: cuadrada)? de (\d+(?:\.\d+)?)/))return`raiz de ${m[1]} = ${fmt(Math.sqrt(+m[1]))}`;
if(m=low.match(/(\d+(?:\.\d+)?)\s*%\s*de\s*(\d+(?:\.\d+)?)/))return`${m[1]}% de ${m[2]} = ${fmt(m[1]*m[2]/100)}`;
if(m=low.match(/(-?\d+(?:\.\d+)?)\s*([a-z]+)\s+(?:a|en)\s+([a-z]+)/)){const f=U[m[2]+">"+m[3]];if(f)return`${m[1]} ${m[2]} = ${fmt(f(+m[1]))} ${m[3]}`}
if(m=low.match(/capital de ([a-z ]+)/)){const c=CAP[m[1].trim()];if(c)return`La capital de ${m[1].trim()} es ${c}`}
if(m=raw.match(/(?:me llamo|mi nombre es)\s+([A-Za-zÁ-ú]+)/i)){name=m[1];return`¡Mucho gusto, ${name}! Yo soy 4NMNN, creado por ZARATE.`}
if(/como me llamo|cual es mi nombre/.test(low))return name?`Te llamas ${name}`:"Aún no me lo dices. Escribe «me llamo ...».";
let s=low.replace(/elevado a/g,"**").replace(/\bmas\b/g,"+").replace(/\bmenos\b/g,"-").replace(/\bpor\b|\bx\b/g,"*").replace(/\b(?:entre|dividido)\b/g,"/").replace(/\^/g,"**").replace(/,/g,".").replace(/[a-z¿?¡!=\s]/g,"");
if(/^[\d+\-*/().%]+$/.test(s)&&/\d.*[+\-*/%].*\d/.test(s)){try{const v=Function('"use strict";return('+s+')')();if(isFinite(v))return`${s.replace(/\*\*/g,"^")} = ${fmt(v)}`}catch(e){}}
return null}

function find(t){const w=t.trim().split(" ");let best=null,bs=0;
for(const e of KB){let s=0;for(const k of e.k){
if(t.includes(" "+k+" ")||(k.length>4&&t.includes(k)))s+=k.split(" ").length*3+k.length/4;
else if(!k.includes(" ")&&k.length>4&&w.some(x=>x.length>3&&lev(x,k)<=1))s+=2}
if(s>bs){bs=s;best=e}}
return bs>=2?best:null}

