    let s = raw.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    s = s.replace(/raiz cuadrada de\\s*([0-9.]+)/, 'sqrt($1)');
    s = s.replace(/raiz de\\s*([0-9.]+)/, 'sqrt($1)');
    s = s.replace(/por ciento/g,'%');
    const pct = s.match(/([0-9.]+)\\s*%\\s*de\\s*([0-9.]+)/);
    if(pct) return `${number(pct[1])*number(pct[2])/100}`;
    if(s.includes('sqrt(')){
      const m=s.match(/sqrt\\(([-+]?\\d+(?:\\.\\d+)?)\\)/); if(m) return String(Math.sqrt(number(m[1])));
    }
    const expr=s.replace(/[^0-9+*/().% -]/g,'').trim();
    if(!expr || !/[+*/()-]/.test(expr) || expr.length>80) return null;
    if(!/^[0-9+*/().% -]+$/.test(expr)) return null;
    try{
      const normalized=expr.replace(/(\\d+(?:\\.\\d+)?)%/g,'($1/100)');
      const result=Function('"use strict";return ('+normalized+')')();
      if(Number.isFinite(result)) return String(Math.round(result*100000000)/100000000);
    }catch(e){}
