    let m=t.match(/(-?\\d+(?:[.,]\\d+)?)\\s*(c|celsius|grados celsius)\\s*(a|en)\\s*(f|fahrenheit)/);
    if(m){const c=number(m[1]);return `${c} grados Celsius equivalen a ${(c*9/5+32).toFixed(2)} grados Fahrenheit.`;}
