    if(m){const f=number(m[1]);return `${f} grados Fahrenheit equivalen a ${((f-32)*5/9).toFixed(2)} grados Celsius.`;}
    m=t.match(/(-?\\d+(?:[.,]\\d+)?)\\s*(litros?|l)\\s*(a|en)\\s*(mililitros?|ml)/);
    if(m){const l=number(m[1]);return `${l} litros equivalen a ${l*1000} mililitros.`;}
    m=t.match(/(-?\\d+(?:[.,]\\d+)?)\\s*(mililitros?|ml)\\s*(a|en)\\s*(litros?|l)/);
