 function n(x){return String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9%+\-*/().?¿!\s]/g,' ').replace(/\s+/g,' ').trim();}
 function keyFor(q){let t=n(q);Object.keys(alias).forEach(k=>{t=t.replace(new RegExp('\\b'+k+'\\b','g'),alias[k]);});for(const k of Object.keys(QUALITY_KB)){if(t===k||t.includes(k))return k;}return null;}
