 function response(q,kind){const k=keyFor(q);if(!k)return null;const e=QUALITY_KB[k];let text=e[0];if(kind==='example')text='Ejemplo práctico: '+e[1];else if(kind==='simple')text='Explicación sencilla: '+e[0]+' '+e[1];else if(kind==='deep')text=e[0]+' '+e[1]+' Área: '+e[3]+'. Nivel recomendado: '+e[2]+'.';else if(kind==='summary')text='Resumen: '+e[0].split('. ')[0]+'.';else if(mode(q)===0)text='En palabras sencillas: '+e[0]+' '+e[1];else if(mode(q)===2)text=e[0]+' '+e[1]+' Categoría: '+e[3]+'.';return text+'\n\nPuedes elegir una opción para continuar: explicación sencilla, ejemplo, explicación profunda o resumen.';}
