(function(){
  'use strict';
  if(window.__4NMNN_TEST_SYSTEM__) return;
  window.__4NMNN_TEST_SYSTEM__ = true;

  var tests = [
    {name:'Definición de carro',question:'¿Qué es un carro?',must:['carro','vehículo'],forbidden:['pH','disolución acuosa']},
    {name:'Definición de pH',question:'¿Qué es el pH?',must:['pH','ácida','básica'],forbidden:['carro','automóvil']},
    {name:'Sinónimo de automóvil',question:'¿Qué es un automóvil?',must:['carro','vehículo'],forbidden:['pH']},
    {name:'Función de un sensor',question:'¿Para qué sirve un sensor?',must:['detectar','medir'],forbidden:['pH indica']},
    {name:'Concepto de agua',question:'Explícame qué es el agua',must:['agua'],forbidden:['carro','pH indica']},
    {name:'ESP32',question:'¿Qué es una ESP32?',must:['ESP32'],forbidden:['carro','pH indica']},
    {name:'Ejemplo solicitado',question:'Dame un ejemplo de energía',must:['ejemplo','energ'],forbidden:['pH indica']},
    {name:'Pregunta desconocida',question:'¿Qué es un objeto inventado llamado zafiroxul?',must:['no encontr','no tengo','no conozco','base'],forbidden:['pH indica','El pH indica qué tan']},
    {name:'Conversión de temperatura',question:'30 celsius a fahrenheit',must:['86'],forbidden:['pH indica']},
    {name:'Diferencia entre pH y turbidez',question:'¿Cuál es la diferencia entre pH y turbidez?',must:['pH','turbidez'],forbidden:['carro']},
    {name:'Causa de la lluvia',question:'¿Por qué ocurre la lluvia?',must:['agua','condens','precipit'],forbidden:['pH indica']},
    {name:'Resumen',question:'Resume qué es la fotosíntesis',must:['fotosíntesis','luz','planta'],forbidden:['pH indica']},
    {name:'Pregunta de seguimiento',question:'Explícame más sobre el pH',must:['pH'],forbidden:['carro','automóvil']},
    {name:'Saludo',question:'Hola',must:['hola','4NMNN'],forbidden:['pH indica']},
    {name:'Seguridad del sistema',question:'¿Qué hago si detecto una fuga de agua?',must:['fuga','bomba','cerrar','detener'],forbidden:['pH indica']}
  ];

  function normalize(value){
    return String(value==null?'':value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
  }
  function includesAny(text, words){
    var t=normalize(text);
    return (words||[]).some(function(word){return t.indexOf(normalize(word))!==-1;});
  }
  function countMatches(text, words){
    var t=normalize(text);
    return (words||[]).filter(function(word){return t.indexOf(normalize(word))!==-1;}).length;
  }
  function executeTest(test){
    var answerText='';
    var error='';
    try{
      if(typeof window.answer!=='function') throw new Error('El motor window.answer no está disponible');
      answerText=String(window.answer(test.question)||'');
    }catch(err){error=err&&err.message?err.message:String(err);}
    var required=test.must||[];
    var found=countMatches(answerText,required);
    var minimum=required.length>=3?2:1;
    var missing=required.filter(function(word){return normalize(answerText).indexOf(normalize(word))===-1;});
    var forbidden=(test.forbidden||[]).filter(function(word){return normalize(answerText).indexOf(normalize(word))!==-1;});
    var passed=!error && answerText.length>0 && found>=minimum && forbidden.length===0;
    return {test:test,answer:answerText,error:error,found:found,missing:missing,forbidden:forbidden,passed:passed};
  }
  function escapeHtml(value){return String(value).replace(/[&<>"']/g,function(ch){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch];});}
  function render(results){
    var summary=document.getElementById('4nmnn-test-summary');
    var container=document.getElementById('4nmnn-test-results');
    if(!summary||!container)return;
    var passed=results.filter(function(r){return r.passed;}).length;
    summary.textContent='Resultado: '+passed+' de '+results.length+' pruebas superadas. '+(passed===results.length?'No se detectaron fallos en este conjunto.':'Hay pruebas que necesitan revisión.');
    container.innerHTML=results.map(function(r){
      var color=r.passed?'#63e6a8':'#ff9b9b';
      var details=r.error?'Error: '+r.error:'Respuesta: '+r.answer;
      if(r.missing.length) details+=' | Faltan indicios: '+r.missing.join(', ');
      if(r.forbidden.length) details+=' | Términos no permitidos: '+r.forbidden.join(', ');
      return '<div style="border:1px solid '+color+'55;border-radius:12px;padding:9px;background:#102c3d;">'+
        '<div style="font-weight:700;color:'+color+';">'+(r.passed?'PASS':'REVISAR')+' · '+escapeHtml(r.test.name)+'</div>'+
        '<div style="font-size:12px;color:#b8cbd5;margin-top:3px;">Pregunta: '+escapeHtml(r.test.question)+'</div>'+
        '<div style="font-size:12px;color:#e8f5fa;margin-top:5px;white-space:pre-wrap;">'+escapeHtml(details)+'</div>'+ '</div>';
    }).join('');
  }
  function runTests(){
    var results=tests.map(executeTest);
    window.__4NMNN_LAST_TEST_RESULTS__=results;
    render(results);
    return results;
  }
  window.run4NMNNTests=runTests;
  var button=document.getElementById('4nmnn-run-tests');
  if(button)button.addEventListener('click',runTests);
})();

