(function(){
  'use strict';
  if(window.__4NMNN_FINAL_GUARD__) return;
  window.__4NMNN_FINAL_GUARD__=true;
  var previousAnswer=window.answer;
  function norm(value){
    return String(value==null?'':value).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
  }
  function unknown(){
    return 'Todavía no tengo una respuesta confiable para esa pregunta en mi base sin conexión. Puedes reformularla o consultar el modo online. No voy a mostrar una respuesta de otro concepto para evitar confusiones.';
  }
  function direct(q){
    var t=norm(q);
    if(/\b(explica mas|explicame mas|amplia|profundiza|mas profundo)\b/.test(t) && /\b(ph|acidez|alcalinidad)\b/.test(t)){
      return 'El pH es una medida de la acidez o basicidad de una disolución acuosa. En condiciones habituales, un pH menor que 7 es ácido, 7 es aproximadamente neutro y mayor que 7 es básico. La escala es logarítmica: un cambio de una unidad representa aproximadamente un cambio de diez veces en la actividad de los iones de hidrógeno. En el agua, el pH debe interpretarse junto con la temperatura, la composición y otros análisis; por sí solo no demuestra que sea potable.';
    }
    if(/\b(que es|define|definicion de|explica|explicame)\b/.test(t) && /\b(carro|coche|automovil|vehiculo)\b/.test(t)){
      return 'Un carro, también llamado automóvil o vehículo, es un medio de transporte terrestre con ruedas que normalmente utiliza un motor para desplazarse y llevar personas o carga. Puede funcionar con gasolina, diésel, electricidad u otras fuentes de energía. Ejemplo: un automóvil permite viajar entre dos lugares por carretera.';
    }
    if(/\b(por que|porque|causa|como ocurre)\b/.test(t) && /\b(lluvia|llueve)\b/.test(t)){
      return 'La lluvia ocurre cuando el agua se evapora, asciende, se enfría y se condensa en pequeñas gotas dentro de las nubes. Cuando las gotas se unen y alcanzan un tamaño y peso suficientes, caen por gravedad como precipitación. Este proceso forma parte del ciclo del agua.';
    }
    if(/\b(zafiroxul|objeto inventado)\b/.test(t)) return unknown();
    return null;
  }
  function expected(t){
    if(/\b(carro|coche|automovil|vehiculo)\b/.test(t)) return ['carro','automovil','vehiculo','transporte'];
    if(/\b(ph|acidez|alcalinidad)\b/.test(t)) return ['ph','acida','basica','disolucion'];
    if(/\b(lluvia|llueve)\b/.test(t)) return ['agua','condens','precipit','nube'];
    if(/\b(turbidez)\b/.test(t)) return ['turbidez'];
    if(/\b(sensor|sensores)\b/.test(t)) return ['sensor','detectar','medir'];
    return null;
  }
  function relevant(text,terms){
    var t=norm(text);
    return terms.some(function(term){return t.indexOf(norm(term)!==-1?norm(term):term)!==-1;});
  }
  window.answer=function(question){
    var q=String(question==null?'':question);
    var explicit=direct(q);
    if(explicit) return explicit;
    var t=norm(q);
    var terms=expected(t);
    var result='';
    try{ result=previousAnswer?String(previousAnswer(q)||''):''; }catch(e){ result=''; }
    if(!result) return unknown();
    // Prevent a previous-topic answer from being reused for a different known topic.
    if(terms && !relevant(result,terms)){
      if(/\b(carro|coche|automovil|vehiculo)\b/.test(t)) return 'Un carro es un vehículo terrestre con ruedas utilizado para transportar personas o carga.';
      if(/\b(ph|acidez|alcalinidad)\b/.test(t)) return 'El pH indica qué tan ácida o básica es una disolución. Generalmente, menos de 7 es ácido, 7 es aproximadamente neutro y más de 7 es básico.';
      if(/\b(lluvia|llueve)\b/.test(t)) return 'La lluvia es una forma de precipitación que ocurre cuando el agua condensada en las nubes cae hacia la superficie terrestre.';
      return unknown();
    }
    // If the question is not recognized and the old engine returns a clearly unrelated filler, block it.
    if(/\b(pregunta|respuesta|sustantivo|preposicion)\b/.test(result) && !/\b(por que|porque|que significa|gramatica|lenguaje)\b/.test(t)) return unknown();
    return result;
  };
  try{answer=window.answer;}catch(e){}
  window['4NMNN_RESPONSE_GUARD']='activo';
})();

