function allEntries(){return Object.entries(entries).filter(([k])=>k!=='fotosintesis2');}
function detectTopic(t){
 const s=cleanText(t);
 if(/\bzafiroxul\b/.test(s)) return 'unknown';
 let best=null,score=0;
 for(const [key,d] of allEntries()){
   for(const a of d.aliases){
     const aa=cleanText(a);
     const re=new RegExp('(?:^|\\s)'+aa.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:$|\\s)','i');
     if(re.test(s)){const points=aa.length>5?3:2;if(points>score){best=key;score=points;}}
   }
 }
 return best;
}
function detectIntent(t){
 const s=cleanText(t);
 if(/\b(resume|resumen|en pocas palabras)\b/.test(s))return 'summary';
 if(/\b(ejemplo|ejemplos|ejemplificar)\b/.test(s))return 'example';
 if(/\b(para que sirve|para que se usa|funcion|utilidad|uso)\b/.test(s))return 'function';
 if(/\b(como funciona|como se hace|pasos|procedimiento|proceso)\b/.test(s))return 'process';
 if(/\b(explica mas|explicame mas|amplia|profundiza|mas profundo|detalla)\b/.test(s))return 'expand';
 if(/\b(por que|porque|causa|como ocurre|como se produce)\b/.test(s))return 'cause';
 if(/\b(que es|que significa|define|definicion|significado)\b/.test(s))return 'definition';
 return 'general';
}
function continuation(t){return /\b(eso|esto|ese tema|lo anterior|el anterior|otro ejemplo|mas facil|amplia|profundiza|explica mas)\b/.test(cleanText(t));}
function unknown(){return 'No tengo una definición confiable de ese tema en mi base offline. Puedes reformular la pregunta o activar el modo online. No voy a reemplazar tu pregunta por una respuesta de otro concepto.';}
function format(topic,intent){
 const d=entries[topic];if(!d)return unknown();
 if(intent==='summary')return d.summary||d.definition;
 if(intent==='example')return d.example||d.definition;
 if(intent==='function')return d.function||d.definition;
 if(intent==='process')return d.process||d.definition;
 if(intent==='expand')return [d.definition,d.function,d.example].filter(Boolean).join(' ');
 if(intent==='cause'&&topic==='lluvia')return d.definition+' La causa inmediata es que las gotas o cristales alcanzan un tamaño suficiente para caer por gravedad.';
 return d.definition;
}
function save(topic,intent){try{localStorage.setItem('4nmnn_robust_context',JSON.stringify({topic,intent,at:Date.now()}));}catch(e){}currentTopic=topic;currentIntent=intent;previousTopic=topic;}
function load(){try{return JSON.parse(localStorage.getItem('4nmnn_robust_context')||'{}');}catch(e){return {};}}
function route(question){
 const raw=String(question??'').trim();if(!raw)return '';
 const t=cleanText(raw);
 if(/^(hola|buenas|buenos dias|buenas tardes|buenas noches)\b/.test(t))return 'Hola. Soy 4NMNN. Puedes preguntarme por conceptos, funciones, causas, procesos, ejemplos o resúmenes.';
 const intent=detectIntent(t);let topic=detectTopic(t);const old=load();
 if(topic==='unknown')return unknown();
 if(!topic&&continuation(t))topic=old.topic||currentTopic||previousTopic;
 if(!topic)return unknown();
 save(topic,intent);
 return format(topic,intent);
}
window.answer=route;
try{answer=route;}catch(e){}

