    if(kind==='cause')return base+' Para comprender sus causas, conviene revisar las condiciones que lo producen y distinguir hechos comprobados de hipótesis.';
    if(kind==='compare')return base+' Para compararlo con otro concepto, revisa sus características, finalidad, semejanzas y diferencias.';
    if(kind==='expand')return base+' '+example+' Área relacionada: '+area+'. Puedes profundizar revisando sus componentes, aplicaciones, límites y consecuencias.';
