/* 4NMNN — Versión 1: motor acumulativo de comprensión de preguntas completas */
(function(){
  const STOP=new Set('que es qué es cual cuál como cómo por para una un el la los las de del y o en se me te le lo esto eso esta está sirve significa puedes explicar dime quiero saber necesito'.normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/\s+/));
  const ALIASES={
    'computador':'computadora','ordenador':'computadora','pc':'computadora','cel':'telefono','celular':'telefono','movil':'telefono','móvil':'telefono',
    'inteligencia artificial':'ia','machine learning':'aprendizaje automatico','aprendizaje de maquina':'aprendizaje automatico',
    'p h':'ph','acidez':'ph','suciedad del agua':'turbidez','microchip':'microcontrolador','microcontrolador esp':'esp32',
    'mate':'matematicas','bio':'biologia','fis':'fisica','quim':'quimica','volley':'voleibol','volleyball':'voleibol',
    'porcentaje':'por ciento','q':'que','k':'que','xq':'porque','pq':'porque','haci':'asi','aser':'hacer','aver':'a ver'
  };
  const INTENTS=[
    {name:'definition',rx:/\b(que es|que significa|define|definicion de|significado de)\b/},
    {name:'function',rx:/\b(para que sirve|que hace|funcion de|utilidad de|uso de)\b/},
    {name:'process',rx:/\b(como funciona|como se hace|como ocurre|cual es el proceso|pasos para)\b/},
    {name:'cause',rx:/\b(por que|porque ocurre|que causa|causas de)\b/},
    {name:'compare',rx:/\b(diferencia entre|diferencias entre|compara|parecido entre)\b/},
    {name:'example',rx:/\b(ejemplo de|dame un ejemplo|ejemplos de)\b/},
    {name:'summary',rx:/\b(resume|resumen de|en pocas palabras|breve)\b/},
    {name:'expand',rx:/\b(explica mas|amplia|mas profundo|profundiza|detalla)\b/}
  ];
  function normalize(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9ñ?¿!.,+\-*/()=\s]/g,' ').replace(/\s+/g,' ').trim();}
  function correct(v){let t=normalize(v);for(const [a,b] of Object.entries(ALIASES)){t=t.replace(new RegExp('\\b'+a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','g'),b);}return t;}
  function intent(t){return (INTENTS.find(x=>x.rx.test(t))||{name:'general'}).name;}
  function cleanTopic(raw){let t=correct(raw);t=t.replace(/\b(que es|que significa|define|definicion de|significado de|para que sirve|que hace|funcion de|utilidad de|uso de|como funciona|como se hace|como ocurre|cual es el proceso|pasos para|por que|porque ocurre|que causa|causas de|diferencia entre|diferencias entre|compara|parecido entre|ejemplo de|dame un ejemplo|ejemplos de|resume|resumen de|en pocas palabras|breve|explica mas|amplia|mas profundo|profundiza|detalla)\b/g,' ');return t.replace(/\b(por favor|me puedes|puedes|quiero saber|necesito saber|explicame|explica|dime)\b/g,' ').replace(/\s+/g,' ').trim();}
  function words(t){return correct(t).split(/\s+/).filter(w=>w.length>2&&!STOP.has(w)&&!/^[?¿!.,]+$/.test(w));}
  function findLocal(topic){
    const candidates=[];
    try{if(typeof V11_ENTRIES!=='undefined')candidates.push(...V11_ENTRIES);}catch(e){}
    try{if(typeof BASE_LOCAL_AMPLIADA!=='undefined')candidates.push(...BASE_LOCAL_AMPLIADA);}catch(e){}
    let best=null,score=0;const q=correct(topic),qw=words(q);
    for(const e of candidates){const key=correct(e.key||e.term||e.word||'');if(!key)continue;let s=0;if(q===key)s=1000;else if(q.includes(key))s=300+key.length;else{const kw=words(key);const hits=kw.filter(w=>qw.includes(w)||q.includes(w)).length;s=hits*35-(Math.max(0,kw.length-hits)*4);if(hits===kw.length&&hits>0)s+=120;}if(s>score){score=s;best=e;}}
    return score>=35?best:null;
  }
  function entryText(e,kind,level){
    if(!e)return null;const d=e.definition||e[0]||'Esta entrada aún no tiene una definición disponible.';const ex=e.example||e[1]||'';let text=d+(ex?' '+ex:'');
    if(kind==='summary')return d.split(/[.!?]/)[0]+'.';
    if(kind==='example')return (ex||'Ejemplo: relaciona este concepto con una situación cotidiana para comprenderlo mejor.');
    if(kind==='function')return text+' Su utilidad depende del contexto y de la forma en que se aplica.';
    if(kind==='process')return text+' Para estudiarlo, identifica sus etapas, los elementos que intervienen y el resultado de cada etapa.';
    if(kind==='cause')return text+' Para comprender sus causas, revisa las condiciones que lo producen y distingue causas directas de factores asociados.';
    if(kind==='compare')return text+' Para compararlo con otro concepto, revisa sus semejanzas, diferencias, propósito y límites.';
    if(kind==='expand')return text+' Ampliación: relaciónalo con sus causas, consecuencias, aplicaciones, límites y conceptos relacionados.';
    if(level==='basico')return 'Explicación sencilla: '+text+' Piensa en ello como una idea que puedes observar en un ejemplo de la vida diaria.';
    if(level==='avanzado')return text+' Nivel avanzado: también conviene estudiar sus condiciones, unidades cuando existan, evidencias, límites y aplicaciones.';
    return text;
  }
  function level(t){if(/\b(nino|nina|primaria|facil|sencillo|simple)\b/.test(t))return 'basico';if(/\b(universidad|avanzado|profundo|tecnico|detallado)\b/.test(t))return 'avanzado';return 'medio';}
  function contextTopic(t){
    if(!/\b(eso|esto|ese|esa|el anterior|lo anterior|dicho|tema)\b/.test(t))return null;
    try{const a=JSON.parse(localStorage.getItem('4nmnn_v11_memory')||'[]').filter(x=>x.role==='user');return a.length?a[a.length-1].text:null;}catch(e){return null;}
  }
  function response(raw){
    const original=String(raw||'');let t=correct(original);if(!t)return null;
    const follow=/\b(explica mas|amplia|otro ejemplo|mas facil|resumelo|profundiza|detalla)\b/.test(t);
    const source=follow?(contextTopic(t)||original):original;const kind=intent(t);const topic=cleanTopic(source);let e=findLocal(topic);
    if(!e && source!==original)e=findLocal(cleanTopic(original));
    if(e)return entryText(e,follow?'expand':kind,level(t));
    if(/\b(hola|buenas|buenos dias|buenas tardes|buenas noches)\b/.test(t))return 'Hola. Soy 4NMNN. Puedes hacerme preguntas completas y pedir una explicación sencilla, un ejemplo, un resumen o una ampliación.';
    if(/\b(no entiendo|no comprendo)\b/.test(t))return 'Puedo explicarlo de otra manera. Escribe el concepto o la pregunta y añade “explicación sencilla” para recibir una respuesta más fácil.';
    if(/\b(ayuda|que puedes hacer|qué puedes hacer)\b/.test(t))return 'Puedo definir conceptos, explicar funciones y procesos, dar ejemplos, resumir temas y resolver algunas operaciones. Mi conocimiento offline tiene límites y puede necesitar una pregunta más específica.';
    return null;
  }
  const old=window.answer;
  window.answer=function(raw){const r=response(raw);if(r){try{const a=JSON.parse(localStorage.getItem('4nmnn_v11_memory')||'[]');a.push({role:'user',text:String(raw),at:Date.now()},{role:'assistant',text:r,at:Date.now()});localStorage.setItem('4nmnn_v11_memory',JSON.stringify(a.slice(-40)));}catch(e){}return r;}return old?old(raw):'No encontré una respuesta en mi base offline. Intenta escribir la pregunta con otras palabras.';};
  try{answer=window.answer;}catch(e){}
  window['4NMNN_COMPRENSION_COMPLETA']=true;
  window['4NMNN_COMPRENSION_CAPACIDADES']=['clasificacion de intencion','limpieza de preguntas','sinonimos y correccion','referencias contextuales','niveles de explicacion','seguimiento offline'];
})();

