  function adapt(e,l){if(l==='basico')return e.definition+' Explicado fácil: piensa en ello como una idea que podemos observar en la vida diaria. '+e.example;if(l==='avanzado')return e.definition+' Análisis: conviene relacionarlo con sus causas, límites, unidades, evidencias y posibles aplicaciones. '+e.example;return e.definition+' '+e.example;}
  function findConcept(t){let best=null,score=0;for(const e of V11_ENTRIES){const k=norm(e.key);let s=0;if(t===k)s=1000;if(t.includes(k))s=Math.max(s,100+k.length);const ws=k.split(' ');const hits=ws.filter(w=>w.length>2&&t.includes(w)).length;if(hits===ws.length)s=Math.max(s,80+hits*10);if(s>score){score=s;best=e;}}return score>=80?best:null;}
  function calculator(raw){const t=norm(raw);if(!/(calcula|cuanto es|cuánto es|resuelve|resultado de)/.test(t))return null;const expr=t.replace(/(calcula|cuanto es|cuánto es|resuelve|resultado de|por favor|el resultado es)/g,'').replace(/x/g,'*').replace(/,/g,'.').trim();if(!/^[0-9+\-*/().%\s]+$/.test(expr)||!/[0-9]/.test(expr))return null;try{const safe=expr.replace(/(\d+(?:\.\d+)?)%/g,'($1/100)');const result=Function('"use strict";return ('+safe+')')();if(Number.isFinite(result))return 'Resultado: '+result+'. Operación interpretada: '+expr+'. Revisa las unidades y el orden de las operaciones.';}catch(e){}return 'No pude interpretar la operación. Escríbela, por ejemplo: calcula (25 + 15) / 5.';}
  function reasoning(raw){const t=norm(raw);if(/por que|porque|como funciona|explica el proceso/.test(t)&&/filtr|agua/.test(t))return 'El agua puede tratarse por etapas: primero se retienen partículas grandes, luego se filtran partículas más pequeñas y, cuando corresponde, se aplica una desinfección validada. El pH y la turbidez no bastan para certificar potabilidad.';if(/si.*entonces|que pasaria|qué pasaría/.test(t))return 'Para razonar una situación: identifica la condición inicial, describe la causa posible, estima la consecuencia y propone una forma segura de comprobarla. No confundas una hipótesis con un hecho confirmado.';return null;}
  function followup(raw){const t=norm(raw);if(/explica mas|amplia|otro ejemplo|ejemplo|resumelo|resumir|mas facil/.test(t)){const c=findConcept(norm(lastConcept()));if(c)return 'Continuación sobre '+c.key+': '+adapt(c,level(t));return 'Dime el concepto que quieres ampliar y puedo ofrecer una definición, ejemplo, pasos, ventajas, límites o un resumen.';}return null;}
  function engine(raw){const original=String(raw||'');const t=fix(original);if(!t)return null;const calc=calculator(t);if(calc)return calc;const r=reasoning(t);if(r)return r;const f=followup(t);if(f)return f;if(/^(hola|buenas|buenos dias|buenas tardes|buenas noches)/.test(t))return 'Hola. Soy 4NMNN y puedo consultar mi conocimiento educativo sin conexión.';if(/sin internet|modo offline/.test(t))return 'Estoy usando mi base local. Puedo explicar conceptos, dar ejemplos y resolver operaciones sencillas, pero no tengo acceso a información web actualizada en este modo.';let query=t.replace(/^(que es|qué es|que significa|define|definicion de|explica|explicame|dime|para que sirve|como funciona|cómo funciona|cual es|cuál es)\s*/,'').trim();Object.keys(V11_ALIASES).forEach(k=>{if(query===k||query.includes(k))query=query.replace(new RegExp('\\b'+k+'\\b','g'),norm(V11_ALIASES[k]));});const c=findConcept(query);if(c)return adapt(c,level(t));return null;}
  const previous=window.answer;
  window.answer=function(raw){const out=engine(raw);if(out){remember('user',raw);remember('assistant',out);return out;}const old=previous?previous(raw):null;const final=old||'No encontré ese concepto en mi base offline. Puedes formular la pregunta de otra manera o conectarte a internet para ampliar la información.';remember('user',raw);remember('assistant',final);return final;};
