function $(id){ return document.getElementById(id); }
function announce(msg){
  try{
    var el = $('announcer');
    if(el) el.textContent = msg;
  }catch(e){}
}

// --- Manejo global de errores no controlados: evita que la app quede rota en silencio ---
window.addEventListener('error', function(e){
  console.error('4NMNN error:', (e && (e.error||e.message)) || e);
  announce('Ocurrió un problema y 4NMNN lo evitó automáticamente.');
});
window.addEventListener('unhandledrejection', function(e){
  console.error('4NMNN promesa rechazada:', e && e.reason);
});

// --- Envuelve funciones globales clave con try/catch y limitación de frecuencia (anti-spam) ---
function wrapSafe(name, minGapMs){
  var original = window[name];
  if(typeof original !== 'function') return;
  var last = 0;
  window[name] = function(){
    var now = Date.now();
    if(minGapMs && (now - last) < minGapMs){
      announce('Espera un momento antes de repetir esta acción.');
      return;
    }
    last = now;
    try{
      return original.apply(this, arguments);
    }catch(err){
      console.error('4NMNN ('+name+'):', err);
      announce('No se pudo completar la acción. Intenta de nuevo.');
    }
  };
}
wrapSafe('sim', 0);
wrapSafe('rnd', 800);
wrapSafe('clean', 1500);
wrapSafe('send', 400);
wrapSafe('diag', 400);
wrapSafe('start', 0);

// --- aria-pressed en el botón de voz, sincronizado con tv() ---
var originalTv = window.tv;
if(typeof originalTv === 'function'){
  window.tv = function(){
    var r = originalTv.apply(this, arguments);
    try{
      var btn = $('vb');
      if(btn) btn.setAttribute('aria-pressed', btn.textContent.indexOf('ON') !== -1 ? 'true' : 'false');
    }catch(e){}
    return r;
  };
}

// --- aria-current en la navegación inferior, sincronizado con pg() ---
var originalPg = window.pg;
if(typeof originalPg === 'function'){
  window.pg = function(p){
    var r = originalPg.apply(this, arguments);
    try{
      document.querySelectorAll('nav button').forEach(function(b){ b.removeAttribute('aria-current'); });
      var on = $('n-' + p);
      if(on){
        on.setAttribute('aria-current', 'page');
        announce('Sección ' + on.textContent + ' abierta.');
      }
    }catch(e){}
    return r;
  };
}

// --- Aviso visual en vivo si el pH del simulador sale del rango seguro ---
